arguments.command:
curl -s -X POST https://api.linear.app/graphql \
  -H 'Content-Type: application/json' \
  -H 'Authorization: Bearer <TOKEN>' \
  --data '{
    "query": "query {
      issues(state: \"active\", first: 50) {
        nodes {
          id
          identifier
          title
          priority
          assignee { name email }
          state { name }
        }
      }
    }"
  }'

